-- Запись журнала обновлений (ADR 0077): выпуск 31 — цикл заявки на обслуживание оргтехники.
--
-- Схему миграция не трогает — она только заводит запись выпуска, как 0102, 0109, 0113, 0116, 0125,
-- 0126, 0128, 0134, 0135, 0140, 0158, 0159 и 0160 (ADR 0077 §4).
--
-- Хвост версии — по последнему решению блока (§2): работа целиком описана ADR 0125, и `0.1.31.0125`
-- монотонно продолжает `0.1.30.0124`. Подверсия здесь не нужна: у блока своё решение есть.
--
-- `released_on` отвечает пользователю на вопрос «с какого числа это работает» и стоит по дню, когда
-- работа доехала до main (§3).
--
-- Схему этого же выпуска меняют соседние миграции 0161 (значение перечисления `on_hold`) и 0162
-- (поля заморозки, CHECK'и, индексы очередей). Колонка `due_date` в них намеренно не удаляется:
-- `DROP COLUMN` необратим и идёт своим релизом по протоколу выката.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  38, '0.1.31.0125', '2026-08-19', 'Состояние заявки одним столбцом, «Отложена» и обязательный закрывающий документ', '{125}',
  '[
    {"kind":"feature","text":"Состояние заявки на обслуживание читается одним столбцом «Статус»: тег с возрастом, под ним — что требуется и от кого. Прежние соседние «Ждёт» и «От вас требуется» говорили об одном и том же и читались как три разных факта; подпись «ход не за вами» вообще знала три статуса из десяти"},
    {"kind":"feature","text":"Подпись «Вам: …» кликабельна и открывает то самое окно, к которому зовёт: визу ИТ, назначение сервиса, смету, согласование, закрытие работ, приёмку. Список перестал быть перечнем напоминаний, за которыми идут в меню из шести пунктов"},
    {"kind":"feature","text":"Появился статус «Отложена»: заявку замораживают с обязательной причиной и возвращают ровно в тот статус, из которого отложили. Откладывает тот, кто ведёт заявки, — оператор оргтехники и администратор; исполнитель о задержке сообщает, а решает заказчик работ"},
    {"kind":"feature","text":"Принять работу нельзя без закрывающего документа: годится любой из трёх — акт, счёт или гарантийный талон. Бумага подшивается прямо в окне приёмки, окно при этом остаётся открытым и кнопка отпирается сразу"},
    {"kind":"improvement","text":"Очередь «Ожидаются документы» стала списком того, что нельзя принять: раньше она требовала и акт, и счёт — то есть бумагу, которая приёмке не мешала. Эта же нехватка видна прямо в столбце состояния строкой «Вам: нужен закрывающий документ»"},
    {"kind":"improvement","text":"Отложенная заявка не ждёт никого: она не попадает ни в очередь «Ждут меня», ни в счётчик раздела. Но техника остаётся занятой — вторую заявку на неё завести нельзя, пока первая не закрыта"},
    {"kind":"improvement","text":"Срочность заморозку переживает: после возврата красная метка работает без повторного объяснения. Наверх списка отложенная при этом не поднимается — первой строкой стоит то, за что берутся сейчас"},
    {"kind":"improvement","text":"У отложенной заявки остаются возобновление, отмена и запись перемещения техники: аппарат ездит независимо от статуса заявки. Правка, срочность и обычные ходы закрыты — сначала возобновите"},
    {"kind":"fix","text":"Поле «Желаемый срок» убрано вместе с меткой «просрочена» и фильтром «Просроченные». Срок, который ничего не запирал, через месяц стоял просроченным у половины заявок; давность теперь читается возрастом в текущем статусе — он точнее отвечает на вопрос «кто тянет»"},
    {"kind":"fix","text":"Пункт «Согласование ИТ» больше не показывается сервисной компании: у неё это была та же дуга под чужим именем, окно открывалось, а сервер отвечал отказом"},
    {"kind":"fix","text":"Пункт «Удалить» показывается только тем, кому снос в архив действительно разрешён: раньше он предлагался и там, где сервер отвечал отказом"},
    {"kind":"fix","text":"Приёмка и снятие документа больше не спорят друг с другом: одновременные попытки выстраиваются в очередь, и принятая заявка не остаётся без бумаги, по которой её приняли"},
    {"kind":"fix","text":"Последний закрывающий документ у принятой заявки больше не снимается — иначе требование бумаги действовало бы ровно в момент приёмки, а через минуту заявка оставалась бы без подтверждения работы. Ошибочный акт меняют в обратном порядке: сначала подшить верный, потом снять неверный"},
    {"kind":"feature","text":"Сервисная компания записывает примечание к заявке прямо в портале: «запчасть будет 3-го» пишется там же, где заявка и стоит, — в том числе у отложенной. Раньше карточка чужое примечание только показывала, а написать его было нечем"}
  ]'::jsonb
);
